function cookie(e){let t=e=>document.cookie=e,o=()=>{let t=decodeURIComponent(document.cookie).split(";");for(let o=0;o<t.length;o++){let n=t[o].trim().split("=");if(n[0]===e)return n.slice(1).join("=")}},n=(o,n=null)=>{const i=e+"="+o+";path=/";if(null===n)t(i);else{const e=new Date;e.setTime(e.getTime()+1e3*n),t(i+";expires="+e.toUTCString())}};return{value:o,set:n,delete:()=>n("",0),toString:o}}